// dragging the zoomed view. Turn: a sideways drag turns it, all the way round. Move: a drag slides the map under the pointer, as far as the edge of the state.
// Shift + drag does the other one. In Move the canvas takes a finger's up-and-down drags too, so the page is scrolled from outside the map.
let dmode = 'turn';
const BND = FINE.cells.reduce((b, c) => [Math.min(b[0], c.x), Math.max(b[1], c.x), Math.min(b[2], c.y), Math.max(b[3], c.y)], [1e9, -1e9, 1e9, -1e9]);
