  if (drag.pan) { const xr = dx / P.k, yr = dy / (P.k * P.ct); ZC = {x: clamp(drag.zx - (xr * P.cs + yr * P.sn), BND[0], BND[1]), y: clamp(drag.zy - (yr * P.cs - xr * P.sn), BND[2], BND[3])}; }
