  $('#back').hidden = !z; const h = $('#hint'); h.hidden = busy; h.classList.toggle('z0', !z); h.textContent = z ? `${dmode === 'move' ? 'Drag to move' : 'Drag sideways to turn'} · ${TAP.toLowerCase()} to jump there` : `${TAP} anywhere to zoom in`;
