  if (fr.length && lows.length && fr[0].v >= 50) out.from = {mode: fr[0].i, area: null, title: `${cap(SV[fr[0].i].q)} is usually posted as a starting price. ${cap(SV[lows[0].i].q)} is usually posted as one price.`,
    text: `${cap(in10(fr[0].v))} ${SV[fr[0].i].q} prices are posted as a starting price: a plus sign, "from", "and up" or a range. For ${orl(lows.map(x => SV[x.i].q))} it is ${in10(lows.reduce((t, x) => t + x.v, 0) / lows.length)}. The index reads the starting price, so a figure for ${SV[fr[0].i].q} shows where prices begin.`};
