  const f = FIND[i]; tour.i = i; tour.auto = !!auto && !REDUCE.matches; tour.t = 0; tour.dwell = clamp((f.title + ' ' + f.text).split(/\s+/).length * 190, 4500, 9000); /* time to read the card once the map has arrived */ tour.pending = true;
