  $('#cstats').innerHTML = `<div><b>${n0(c.salons)}</b><span>salons priced</span></div><div><b>${n0(c.prices)}</b><span>prices</span></div><div><b>${pub.length} of ${M.services}</b><span>services with a published figure</span></div>`;
  const up = pub.filter(i => dstep(c.v[i][0], SV[i].med) > 5).length, dn = pub.filter(i => dstep(c.v[i][0], SV[i].med) < -5).length, same = pub.length - up - dn;
  $('#csum').innerHTML = (pub.length ? `Of the ${pub.length} services with a published figure in ${esc(c.c)}, <b>${up}</b> sit${up === 1 ? 's' : ''} more than one $5 step above the all-cities median, <b>${dn}</b> sit${dn === 1 ? 's' : ''} more than one step below and <b>${same}</b> ${same === 1 ? 'is' : 'are'} about the same.` : `${esc(c.c)} has too few prices to publish a figure for any one service. It still counts in its region's figures.`)
